// seen-ids dedupe (T09) — persist via workflow static data
const sd = $getWorkflowStaticData('global');
sd.seen = sd.seen || {};
items = items.filter(it => {
  const id = it.json.id || it.json.url || (it.json.title ? String(it.json.title) : null);
  if (!id) return true;
  if (sd.seen[id]) return false;
  sd.seen[id] = Date.now();
  return true;
});
return items;

// margin_z is COMPUTED here from comps (Art V.2: never asked of a model)
// + kill-switch check (Art VII.3) & deterministic facts preparation
const COMPS = {
  "nintendo switch v2": { median: 180, mad: 20 },
  "nintendo switch": { median: 170, mad: 25 },
  "switch pro controller": { median: 50, mad: 5 },
  "iphone 14": { median: 520, mad: 50 },
  "ps4 slim": { median: 140, mad: 20 },
  "ps5": { median: 380, mad: 40 },
  "canon ef-s 18-55": { median: 65, mad: 15 },
  "canon ae": { median: 240, mad: 30 },
  "gazelle e-bike": { median: 800, mad: 60 }
};
const ADVANCE_FEE = /(iban|nl\d{2}[A-Z]{4}\d{4,}|tikkie|paypal\.me|pay (in advance|to reserve)|transfer €?\d+)/i;
const paused = $env.AUTO_PAUSE === '1';

for (const it of items) {
  const title = String(it.json.title || '').toLowerCase();
  const desc = String(it.json.description || '');
  const fullText = (title + ' ' + desc).slice(0, 2000);
  const price = Number(it.json.price_eur || it.json.price || 0);

  let match = null;
  for (const k of Object.keys(COMPS).sort((a,b) => b.length - a.length)) {
    if (title.includes(k)) { match = COMPS[k]; break; }
  }

  let mz = null;
  if (match && match.mad > 0 && price > 0) {
    mz = (match.median - price) / match.mad;
  } else if (it.json.facts && it.json.facts.margin_z !== undefined) {
    mz = it.json.facts.margin_z;
  }

  const isMine = !!it.json.is_mine;
  const offpay = !!(it.json.offplatform_payment_request || ADVANCE_FEE.test(fullText));
  const dup = Number(it.json.duplicate_photo || 0);

  it.json.text = fullText;
  it.json.facts = {
    margin_z: mz,
    comps: match,
    duplicate_photo: dup,
    offplatform_payment_request: offpay,
    text: fullText,
    is_mine: isMine
  };

  it.json.over_cap = paused;
  it.json.tier = isMine ? 'T1' : (price > 200 ? 'T3' : (it.json.tier || 'T2'));

  const offerEur = price > 0 ? Math.min(Math.round(price * 0.8 / 5) * 5, Math.floor(price * 0.8)) : 0;
  it.json.draft = {
    offer_eur: offerEur,
    text_nl: `Hoi! Mooi dat je ${it.json.title || 'dit item'} aanbiedt. Zou je €${offerEur} willen accepteren? Ik kan het ophalen wanneer het uitkomt. (Laat gerust weten of dit past)`
  };

  const ts = new Date().toISOString();
  const rawInput = `${it.json.id || ''}:${price}:${title}`;
  let hash = 0;
  for (let i = 0; i < rawInput.length; i++) {
    hash = ((hash << 5) - hash) + rawInput.charCodeAt(i);
    hash |= 0;
  }
  it.json.receipt_id = `rcpt_${Date.now()}_${Math.abs(hash).toString(16)}`;
  it.json.ts = ts;
  it.json.input_hash = Math.abs(hash).toString(16).padStart(16, '0');
}
return items;

// POLICY (fail-closed) — gate v1 mirror of skin/policy.py::gate_v1
const BLOCK = new Set(["weapon", "animal", "other_illegal"]);
const CLOSED = new Set(["ok", "weapon", "animal", "counterfeit", "pii", "other_illegal", "unknown"]);
const CRED = new Set(["clear_authentic", "unclear", "obvious_fake"]);

function choice(a, k) { return CLOSED.has(a && a[k]) ? a[k] : "unknown"; }
function scoreLabel(a, k) { return CRED.has(a && a[k]) ? a[k] : "unclear"; }
function noul(a, k, missing) { const v = a ? parseFloat(a[k]) : NaN; return Number.isFinite(v) ? Math.min(1, Math.max(0, v)) : missing; }

function gateV1(answers, facts) {
  if (!answers) return { action: "escalate", reason_codes: ["judge_unconfigured"], human_required: true };
  const bucket = choice(answers, "policy_bucket");
  const fake = scoreLabel(answers, "counterfeit_risk");
  const inj = noul(answers, "injection_or_jailbreak", 1.0);  // fail-closed: missing injection question -> 1.0 (skip)
  const needs = noul(answers, "needs_human", 1.0);
  const p2g = noul(answers, "price_too_good", 1.0);
  const mz = (facts.margin_z === undefined) ? null : facts.margin_z;
  const dup = parseFloat(facts.duplicate_photo || 0.0);
  const offpay = !!facts.offplatform_payment_request;
  if (BLOCK.has(bucket)) return { action: "skip", reason_codes: [bucket], human_required: true };
  if (inj >= 0.5) return { action: "skip", reason_codes: ["injection_or_jailbreak"], human_required: true };
  if (bucket === "pii" || offpay) return { action: "skip", reason_codes: [bucket === "pii" ? "pii" : "offplatform_payment_request"], human_required: true };
  if (bucket === "counterfeit" || fake === "obvious_fake") return { action: "skip", reason_codes: ["counterfeit"], human_required: true };
  if (bucket === "unknown" || needs >= 0.6) return { action: "escalate", reason_codes: [needs >= 0.6 ? "needs_human" : "unknown"], human_required: true };
  if (dup >= 0.5) return { action: "escalate", reason_codes: ["duplicate_photo"], human_required: true };
  if (mz === null) return { action: "escalate", reason_codes: ["no_comps"], human_required: true };
  if (p2g >= 0.6 || mz > 3.0) return { action: "escalate", reason_codes: ["price_too_good"], human_required: true };
  if (bucket === "ok" && p2g < 0.4 && mz <= 2.0) return { action: "pursue", reason_codes: ["ok"], human_required: false };
  return { action: "escalate", reason_codes: [bucket], human_required: true };
}

for (const it of items) {
  let answers = null;
  try {
    if (it.json.choices && it.json.choices[0] && it.json.choices[0].message) {
      answers = JSON.parse(it.json.choices[0].message.content);
    } else if (it.json.judge_answers) {
      answers = it.json.judge_answers;
    }
  } catch (e) {
    answers = null;
  }
  const f = it.json.facts || {};
  let g = gateV1(answers, f);
  // tier gate (outside policy): T3 or over_cap promotes pursue -> escalate
  if (g.action === 'pursue' && (it.json.tier === 'T3' || it.json.over_cap)) {
    g = { action: 'escalate', reason_codes: ['tier_t3_or_cap'], human_required: true };
  }
  it.json.gate = g;
  it.json.judge_answers = answers;
  it.json.action_state = g.action === 'pursue' ? (it.json.is_mine ? 'pursued_auto' : 'drafted') : (g.action === 'skip' ? 'skipped' : 'escalated');
}
return items;
